        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            type1, val1 = pre1[i]
            type2, val2 = pre2[i]

            # Numeric identifiers sort before non-numeric
            if type1 != type2:
                return -1 if type1 < type2 else 1

            # Compare values
            if val1 != val2:
                return -1 if val1 < val2 else 1

        # Fewer identifiers sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    # Parse all versions with their original index for stable sort
    parsed = []
    for idx, v in enumerate(versions):
        parsed.append((parse_version(v), idx))

    # Sort by parsed version, keeping original order for equal precedence
    def sort_key(item):
        (major, minor, patch, prerelease), idx = item
        return (major, minor, patch, [-1 if prerelease else 0], idx)

    # Custom sort to handle pre-release comparison
    def compare(item1, item2):
        (major1, minor1, patch1, pre1), idx1 = item1
        (major2, minor2, patch2, pre2), idx2 = item2

        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        pre_cmp = compare_prerelease(pre1, pre2)
        if pre_cmp != 0:
            return pre_cmp

        # Equal precedence, maintain input order
        return -1 if idx1 < idx2 else (1 if idx1 > idx2 else 0)

    from functools import cmp_to_key
    sorted_parsed = sorted(parsed, key=cmp_to_key(compare))

    return [versions[idx] for _, idx in sorted_parsed]

